import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { identifyTeamHandler } from "../handlers/identifyTeamHandler";
import type { ApiError } from "../runtime/client";
import type { TeamIdentificationRequest } from "../types/TeamIdentificationRequest";

type Data = Awaited<ReturnType<typeof identifyTeamHandler>>;
type Vars = { username: string; req: TeamIdentificationRequest };

export function useIdentifyTeam(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => identifyTeamHandler(vars.username, vars.req),
    ...options,
  });
}
